using Godot;
public partial class MigrationScene {
 Label conditionHud;ColorRect recoveryMarker;
 string SurvivalTechDescription(int id)=>id switch{0=>"Portable charcoal filter. Purify untreated water in Y; each batch consumes 1 resin. Clean water has no illness risk.",1=>"Portable membrane purifier. Uses 1 fuel instead of resin per batch. Advanced Waterworks research locks other Survival specializations.",2=>"Comfort kit. Staying within 8m of one of your sleeping bags grants sheltered recovery and improves morale.",3=>"Antibiotic procedure. Crafted medical kits produce twice as many doses. Medical kits cure water illness and support gradual recovery.",4=>"Trail tea kit. Reduces ongoing fatigue loss by 25%; it does not restore fatigue instantly.",5=>"Sealed collection vessels. Boil or filter up to four units per batch instead of two, using the same fuel cost.",_=>"Survival equipment"};
 void DrawConditionHud(){if(conditionHud==null){conditionHud=HudLabel(11);conditionHud.AutowrapMode=TextServer.AutowrapMode.WordSmart;conditionHud.Size=new(300,120);recoveryMarker=new ColorRect{Color=new(.95f,.68f,.29f),MouseFilter=Control.MouseFilterEnum.Ignore,Size=new(2,13)};hudRoot.AddChild(recoveryMarker);}var size=GetViewport().GetVisibleRect().Size;conditionHud.Position=new(size.X-330,90);conditionHud.Text=game.Conditions;conditionHud.Modulate=game.Life.Sickness>0||game.Life.Energy<20?new Color(.95f,.65f,.35f):new Color(.72f,.82f,.67f);recoveryMarker.Visible=game.RecoveryCeiling<game.MaxHealth;recoveryMarker.Position=new(34+230*(float)(game.RecoveryCeiling/game.MaxHealth),size.Y-123);}
}
